mapper.select:
SELECT COLLECTION_ID, MEMBER_ID, TITLE, DESCRIPTION, IS_PUBLIC, CREATED_DT, UPDATED_DT FROM ( SELECT C.COLLECTION_ID, C.MEMBER_ID, C.TITLE, C.DESCRIPTION, C.IS_PUBLIC, TO_CHAR(C.CREATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS CREATED_DT, TO_CHAR(C.UPDATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS UPDATED_DT, ROW_NUMBER() OVER ( ORDER BY C.CREATED_DT DESC, C.COLLECTION_ID DESC ) AS RNUM FROM COLLECTION C
AND C.TITLE LIKE '%' || #{searchWord} || '%'
AND C.MEMBER_ID = #{searchWord}
)
WHERE RNUM BETWEEN ((#{pageNo} - 1) * #{pageSize} + 1) AND (#{pageNo} * #{pageSize})
ORDER BY RNUM
